/* Programming, Data Structures & Algorithms cards. Same fields as data/ps.js.
   Code goes in q as <pre><code>…</code></pre> with &lt; &gt; &amp; escaped. */
(function(){
const R = String.raw;
addCards('dsa', [
/* ---------- Python ---------- */
{id:'mutdef',t:'py',u:'pybasics',lv:2,k:'mcq',name:'Mutable default arguments',sheet:R`\text{def f(x, acc=[]): the same list object is reused across calls}`,
 q:R`What does this print?<pre><code>def add(x, acc=[]):
    acc.append(x)
    return len(acc)

print(add(5), add(6), add(7, []))</code></pre>`,
 o:[R`1 2 1`,R`1 1 1`,R`1 2 3`,R`1 2 2`],a:0,
 why:R`The default list is created once, when the function is defined, so the first two calls share it (lengths 1, then 2). The third call passes a fresh list, so its length is 1.`},
{id:'append',t:'py',u:'pybasics',lv:1,k:'nat',name:'append vs extend',sheet:R`\text{L.append(x) adds one item; L.extend(it) adds each item of it}`,
 q:R`What does this print?<pre><code>A = [1, 2]
A.append([3, 4])
A.extend([5, 6])
print(len(A))</code></pre>`,n:{v:5},
 why:R`<code>append</code> adds the whole list <code>[3, 4]</code> as one element; <code>extend</code> adds 5 and 6 separately: <code>[1, 2, [3, 4], 5, 6]</code>.`},
{id:'alias',t:'py',u:'pybasics',lv:1,k:'mcq',name:'Aliasing vs copying a list',sheet:R`\text{b = a shares the list; b = a[:] or list(a) copies it}`,
 q:R`What does this print?<pre><code>a = [1, 2, 3]
b = a
c = a[:]
b.append(4)
c.append(5)
print(len(a), len(b), len(c))</code></pre>`,
 o:[R`4 4 4`,R`3 4 4`,R`5 4 4`,R`4 4 5`],a:0,
 why:R`<code>b</code> is the same object as <code>a</code>, so appending through b changes a. <code>c</code> is a separate copy, so its append doesn't touch a.`},
{id:'floordiv',t:'py',u:'pybasics',lv:2,k:'mcq',name:'Floor division with negatives',sheet:R`a\,//\,b=\lfloor a/b\rfloor,\ \ a\%b=a-b\lfloor a/b\rfloor`,
 q:R`What does <code>print(-7 // 2, -7 % 2)</code> print in Python?`,
 o:[R`-4 1`,R`-3 -1`,R`-3 1`,R`-4 -1`],a:0,
 why:R`Python's <code>//</code> rounds down (towards −∞), so −3.5 becomes −4. The remainder then has the sign of the divisor: \(-7-2(-4)=1\). C truncates instead and gives −3 and −1.`},
{id:'slice',t:'py',u:'pybasics',lv:1,k:'mcq',name:'Slicing',sheet:R`\text{s[start:stop:step], stop excluded; s[::-1] reverses}`,
 q:R`What does this print?<pre><code>s = "GATEDA"
print(s[::-1][1:4])</code></pre>`,
 o:[R`DET`,R`ADE`,R`ETA`,R`DETA`],a:0,
 why:R`<code>s[::-1]</code> is <code>"ADETAG"</code>. Indices 1, 2, 3 of that are D, E, T; index 4 is excluded.`},
{id:'rangesum',t:'py',u:'pybasics',lv:1,k:'nat',name:'range with a step',sheet:R`\text{range(a, b, s)}: a, a+s, \dots\ \text{while}\ \lt b`,
 q:R`What does <code>print(sum(range(1, 10, 3)))</code> print?`,n:{v:12},
 why:R`<code>range(1, 10, 3)</code> gives 1, 4, 7; the next value, 10, is excluded. \(1+4+7=12\).`},
{id:'setprec',t:'py',u:'pybasics',lv:2,k:'nat',name:'Set operators and precedence',sheet:R`\text{set ops: - (difference) binds tighter than \& , which binds tighter than |}`,
 q:R`What does this print?<pre><code>print(len({1, 2, 3} - {2, 4} | {5}))</code></pre>`,n:{v:3},
 why:R`Difference is applied first: \(\{1,2,3\}-\{2,4\}=\{1,3\}\), then union with \(\{5\}\) gives \(\{1,3,5\}\).`},
{id:'closure',t:'py',u:'pybasics',lv:3,k:'nat',name:'Closures keep their own state',sheet:R`\text{each call of the outer function creates a new enclosed variable}`,
 q:R`What does this print?<pre><code>def make():
    count = [0]
    def inc():
        count[0] += 1
        return count[0]
    return inc

f, g = make(), make()
f(); f(); g()
print(f() + g())</code></pre>`,n:{v:5},
 why:R`f and g each have their own <code>count</code> list. f reaches 3 on its third call and g reaches 2 on its second, so 3 + 2 = 5.`},
{id:'comp',t:'py',u:'pybasics',lv:1,k:'nat',name:'List comprehension with a filter',sheet:R`\text{[expr for x in it if cond]}`,
 q:R`What does <code>print(sum([x * x for x in range(6) if x % 2]))</code> print?`,n:{v:35},
 why:R`<code>x % 2</code> is truthy for odd x: 1, 3, 5. Their squares 1 + 9 + 25 = 35.`},
{id:'swap',t:'py',u:'pybasics',lv:2,k:'mcq',name:'Tuple assignment',sheet:R`\text{a, b = e1, e2: both right-hand sides are evaluated first}`,
 q:R`What does this print?<pre><code>a, b = 1, 2
a, b = b, a + b
a, b = b, a + b
print(a, b)</code></pre>`,
 o:[R`3 5`,R`2 3`,R`3 4`,R`5 8`],a:0,
 why:R`The right side is evaluated before assigning. (1, 2) becomes (2, 3), then (3, 5). This is the Fibonacci step.`},
{id:'loopbrk',t:'py',u:'pybasics',lv:2,k:'mcq',name:'continue and break',sheet:R`\text{continue: skip to next iteration; break: leave the loop}`,
 q:R`What does this print?<pre><code>j = 0
for i in range(1, 8):
    if i % 2 == 0:
        continue
    j += i
    if j > 8:
        break
print(i, j)</code></pre>`,
 o:[R`5 9`,R`7 16`,R`5 4`,R`6 9`],a:0,
 why:R`Even i are skipped. j becomes 1, 4, then 9 at i = 5, which triggers <code>break</code>. The loop variable keeps its last value, 5.`},
{id:'immut',t:'py',u:'pybasics',lv:1,k:'mcq',name:'Immutable strings and tuples',sheet:R`\text{str, tuple, int are immutable; list, dict, set are mutable}`,
 q:R`<code>s = "data"</code>, then <code>s[0] = "D"</code>. What happens?`,
 o:[R`A TypeError: strings are immutable`,R`s becomes "Data"`,R`A new string "D" is assigned to s`,R`An IndexError`],a:0,
 why:R`Strings can't be changed in place. Build a new one instead: <code>s = "D" + s[1:]</code>.`},
{id:'isvseq',t:'py',u:'pybasics',lv:1,k:'mcq',name:'is vs ==',sheet:R`\text{== compares values; is compares object identity}`,
 q:R`<code>a = [1, 2]</code> and <code>b = [1, 2]</code>. What are <code>a == b</code> and <code>a is b</code>?`,
 o:[R`True and False`,R`True and True`,R`False and False`,R`False and True`],a:0,
 why:R`They hold equal values but are two separate list objects. Use <code>is</code> only for identity checks such as <code>x is None</code>.`},
{id:'calls',t:'py',u:'pyrec',lv:2,k:'nat',name:'Counting recursive calls',sheet:R`C(n)=1+C(n-1)+C(n-2)`,
 q:R`How many times is <code>f</code> called in total (including the first call) when evaluating <code>f(5)</code>?<pre><code>def f(n):
    if n &lt;= 1:
        return 1
    return f(n - 1) + f(n - 2)</code></pre>`,n:{v:15},
 why:R`\(C(0)=C(1)=1\) and \(C(n)=1+C(n-1)+C(n-2)\): 3, 5, 9, 15 for n = 2 to 5. Draw the call tree if unsure.`},
{id:'digsum',t:'py',u:'pyrec',lv:1,k:'nat',name:'Recursion on digits',sheet:R`f(n)=n\bmod10+f(\lfloor n/10\rfloor)`,
 q:R`What does this print?<pre><code>def f(n):
    if n == 0:
        return 0
    return n % 10 + f(n // 10)

print(f(4096))</code></pre>`,n:{v:19},
 why:R`It adds the digits: 6 + 9 + 0 + 4 = 19.`},
{id:'fastpow',t:'py',u:'pyrec',lv:2,k:'nat',name:'Fast exponentiation',sheet:R`a^n=(a^{\lfloor n/2\rfloor})^2\cdot a^{n\bmod2},\ \ O(\log n)\ \text{calls}`,
 q:R`How many times is <code>p</code> called in total when evaluating <code>p(2, 13)</code>?<pre><code>def p(a, n):
    if n == 0:
        return 1
    h = p(a, n // 2)
    return h * h if n % 2 == 0 else a * h * h</code></pre>`,n:{v:5},
 why:R`n goes 13, 6, 3, 1, 0: five calls. Halving n each time gives about \(\log_2 n\) calls.`},
{id:'printorder',t:'py',u:'pyrec',lv:2,k:'mcq',name:'Tracing two recursive calls',sheet:R`\text{print between two calls: in-order pattern, }2^n-1\ \text{prints}`,
 q:R`What does this print?<pre><code>def r(n):
    if n > 0:
        r(n - 1)
        print(n, end=" ")
        r(n - 1)

r(3)</code></pre>`,
 o:[R`1 2 1 3 1 2 1`,R`3 2 1 1 2 1 3`,R`1 2 3 2 1`,R`3 2 1`],a:0,
 why:R`r(n) prints r(n−1)'s output, then n, then r(n−1)'s output again. r(1) prints "1", r(2) prints "1 2 1", and r(3) wraps 3 between two copies. It prints \(2^3-1=7\) numbers.`},
{id:'stepswap',t:'py',u:'pyrec',lv:3,k:'mcq',name:'Recursion over list indices',sheet:R`\text{trace index pairs until the stopping condition}`,
 q:R`What does this print?<pre><code>def g(L, i, j):
    if i >= j:
        return
    L[i], L[j] = L[j], L[i]
    g(L, i + 2, j - 2)

L = [1, 2, 3, 4, 5, 6, 7]
g(L, 0, 6)
print(L)</code></pre>`,
 o:[R`[7, 2, 5, 4, 3, 6, 1]`,R`[7, 6, 5, 4, 3, 2, 1]`,R`[7, 2, 3, 4, 5, 6, 1]`,R`[1, 6, 3, 4, 5, 2, 7]`],a:0,
 why:R`Swaps (0, 6) then (2, 4); next i = 4, j = 2 stops. Stepping by 1 instead of 2 would reverse the whole list.`},
{id:'recspace',t:'py',u:'pyrec',lv:1,k:'mcq',name:'Space used by recursion',sheet:R`\text{stack space}=O(\text{max recursion depth})`,
 q:R`A recursive factorial <code>fact(n) = n * fact(n - 1)</code> uses how much extra memory for the call stack?`,
 o:[R`\(O(n)\)`,R`\(O(1)\)`,R`\(O(\log n)\)`,R`\(O(n^2)\)`],a:0,
 why:R`Each pending call keeps a stack frame until the base case returns, and the depth reaches n. An iterative loop needs only \(O(1)\).`},

/* ---------- Data structures ---------- */
{id:'stackuse',t:'ds',u:'stack',lv:1,k:'mcq',name:'Stack applications',sheet:R`\text{stack (LIFO): calls, undo, bracket matching, DFS, expression evaluation}`,
 q:R`Which of these does NOT naturally use a stack?`,
 o:[R`Breadth-first search`,R`Checking balanced brackets`,R`Evaluating a postfix expression`,R`Managing function calls`],a:0,
 why:R`BFS processes vertices in the order discovered, which is first-in-first-out: a queue. DFS is the one that uses a stack.`},
{id:'stackseq',t:'ds',u:'stack',lv:1,k:'mcq',name:'Tracing push and pop',sheet:R`\text{pop returns the most recently pushed item}`,
 q:R`On an empty stack: push 1, push 2, push 3, pop, push 4, pop, pop. In what order are values popped?`,
 o:[R`3, 4, 2`,R`3, 2, 1`,R`1, 2, 3`,R`3, 4, 1`],a:0,
 why:R`After popping 3 the stack is [1, 2]; push 4 gives [1, 2, 4]; then 4 and 2 come off. 1 stays inside.`},
{id:'popord',t:'ds',u:'stack',lv:2,k:'mcq',name:'Possible pop sequences',sheet:R`\text{once } x \text{ is popped, items pushed before } x \text{ come out in reverse order}`,
 q:R`1, 2, 3, 4 are pushed in this order, with pops allowed at any time. Which output sequence is impossible?`,
 o:[R`3, 1, 2, 4`,R`3, 2, 1, 4`,R`2, 1, 4, 3`,R`1, 3, 2, 4`],a:0,
 why:R`To pop 3 first, 1 and 2 must already be inside with 2 on top. So 2 must come out before 1.`},
{id:'postfix',t:'ds',u:'stack',lv:1,k:'nat',name:'Evaluating postfix',sheet:R`\text{operand: push; operator: pop } b,\,a,\ \text{push } a \circ b`,
 q:R`Evaluate the postfix expression <code>2 3 4 * + 5 -</code>.`,n:{v:9},
 why:R`3 × 4 = 12, then 2 + 12 = 14, then 14 − 5 = 9. Note the operand order when subtracting: the second pop is the left operand.`},
{id:'infix',t:'ds',u:'stack',lv:2,k:'mcq',name:'Infix to postfix',sheet:R`\text{higher precedence first; left-to-right for equal precedence}`,
 q:R`The postfix form of <code>a + b * c - d</code> is:`,
 o:[R`<code>a b c * + d -</code>`,R`<code>a b + c * d -</code>`,R`<code>a b c d - * +</code>`,R`<code>a b c * d - +</code>`],a:0,
 why:R`* binds tighter: \(a+(b\cdot c)\) first, then subtract d left to right: \(((a+(b c))-d)\).`},
{id:'catalan3',t:'ds',u:'stack',lv:2,k:'nat',name:'Number of stack permutations',sheet:R`C_n=\frac{1}{n+1}\binom{2n}{n}`,
 q:R`1, 2, 3 are pushed in order onto a stack, with pops allowed at any time. How many different output orders are possible?`,n:{v:5},
 why:R`The count is the Catalan number \(C_3=\frac14\binom63=5\). Of the 6 permutations, only 3, 1, 2 is impossible.`},
{id:'qtrace',t:'ds',u:'queue',lv:1,k:'mcq',name:'Tracing a queue',sheet:R`\text{dequeue returns the earliest enqueued item}`,
 q:R`On an empty queue: enqueue 5, enqueue 8, enqueue 3, dequeue, enqueue 7, dequeue. Which element is now at the front?`,
 o:[R`3`,R`7`,R`8`,R`5`],a:0,
 why:R`5 then 8 leave first. The queue holds 3, 7, with 3 at the front.`},
{id:'deque',t:'ds',u:'queue',lv:2,k:'nat',name:'Double-ended queue',sheet:R`\text{deque: insert/remove at both ends in }O(1)`,
 q:R`On an empty deque: insertLast(4), insertFirst(9), insertLast(2), removeFirst(), insertFirst(6), removeLast(), then <code>a = removeFirst()</code>. What is a?`,n:{v:6},
 why:R`[4] → [9, 4] → [9, 4, 2] → remove 9 → [4, 2] → [6, 4, 2] → remove 2 → [6, 4] → a = 6.`},
{id:'circq',t:'ds',u:'queue',lv:2,k:'fill',name:'Circular queue full test',sheet:R`\text{full}\iff(\text{rear}+1)\bmod n=\text{front}\ \ (\text{one slot kept empty})`,
 q:R`A circular queue in an array of size n keeps one slot empty to tell full from empty. It is full when:`,f:R`(\text{rear}+1)\bmod n=\boxed{\;?\;}`,
 o:[R`\text{front}`,R`\text{rear}`,R`0`,R`n-1`],om:1,a:0,
 why:R`Empty is front = rear. Wasting one slot makes "full" a different condition, so the queue holds at most n − 1 items.`},
{id:'q2s',t:'ds',u:'queue',lv:2,k:'mcq',name:'Queue from two stacks',sheet:R`\text{enqueue: push to }S_1;\ \text{dequeue: if }S_2\text{ empty, move all of }S_1\text{ to }S_2;\ \text{pop }S_2`,
 q:R`A queue is built from two stacks: push to S1 on enqueue; on dequeue, if S2 is empty, pop everything from S1 onto S2, then pop S2. The cost per operation is:`,
 o:[R`\(O(1)\) amortised, though one dequeue can take \(O(n)\)`,R`Always \(O(1)\)`,R`Always \(O(n)\)`,R`\(O(\log n)\)`],a:0,
 why:R`Each element is moved from S1 to S2 at most once, so n operations cost \(O(n)\) in total. The other way round, a stack from two queues, costs \(O(n)\) for push or for pop.`},
{id:'llops',t:'ds',u:'list',lv:1,k:'mcq',name:'Singly linked list costs',sheet:R`\text{head insert/delete }O(1);\ \text{index access, tail delete }O(n)`,
 q:R`A singly linked list has only a head pointer. Which operation is \(O(1)\)?`,
 o:[R`Insert at the head`,R`Access the k-th element`,R`Delete the last node`,R`Insert at the tail`],a:0,
 why:R`Reaching the k-th node, or the node before the tail, means walking from the head. A tail pointer makes tail insertion \(O(1)\), but deleting the last node still needs its predecessor.`},
{id:'lldel',t:'ds',u:'list',lv:2,k:'mcq',name:'Deleting a given node',sheet:R`\text{singly linked: need predecessor }O(n);\ \text{doubly linked: }O(1)`,
 q:R`Given a pointer to a node to delete (and the head), the worst-case time in a singly vs a doubly linked list is:`,
 o:[R`\(O(n)\) for singly, \(O(1)\) for doubly`,R`\(O(1)\) for both`,R`\(O(n)\) for both`,R`\(O(1)\) for singly, \(O(n)\) for doubly`],a:0,
 why:R`Unlinking needs the previous node. A doubly linked node stores it; a singly linked list must search for it from the head.`},
{id:'llrev',t:'ds',u:'list',lv:2,k:'mcq',name:'Reversing a linked list',sheet:R`\text{prev, curr, next pointers: }O(n)\ \text{time, }O(1)\ \text{space}`,
 q:R`Reversing a singly linked list of n nodes in place takes:`,
 o:[R`\(O(n)\) time and \(O(1)\) extra space`,R`\(O(n^2)\) time`,R`\(O(n)\) time and \(O(n)\) extra space at minimum`,R`\(O(n\log n)\) time`],a:0,
 why:R`Walk once, flipping each <code>next</code> pointer while remembering the previous and next nodes. A recursive version uses \(O(n)\) stack space instead.`},
{id:'cycle',t:'ds',u:'list',lv:2,k:'mcq',name:'Detecting a cycle',sheet:R`\text{slow moves 1, fast moves 2: they meet iff there is a cycle}`,
 q:R`Floyd's method moves one pointer one step and another two steps at a time through a linked list. They meet:`,
 o:[R`Only if the list has a cycle`,R`Always, at the middle node`,R`Only if the list length is even`,R`Never, if the list is sorted`],a:0,
 why:R`Without a cycle the fast pointer reaches the end. With one, the gap shrinks by one each step inside the cycle, so they meet. When the fast pointer reaches the end of a list with no cycle, the slow one is at the middle node.`},
{id:'fullbt',t:'ds',u:'tree',lv:1,k:'nat',name:'Full binary tree counts',sheet:R`\text{every node has 0 or 2 children}:\ L=I+1,\ \ n=2L-1`,
 q:R`Every node of a binary tree has 0 or 2 children, and it has 20 leaves. How many nodes does it have?`,n:{v:39},
 why:R`Each internal node adds one extra leaf, so \(L=I+1\): 19 internal nodes, \(n=2L-1=39\).`},
{id:'maxnodes',t:'ds',u:'tree',lv:1,k:'fill',name:'Maximum nodes by height',sheet:R`\text{height }h\ (\text{root at }0):\ n\le2^{h+1}-1,\ \ h\ge\lceil\log_2(n+1)\rceil-1`,
 q:R`A binary tree of height h (a single node has height 0) has at most:`,f:R`n_{\max}=\boxed{\;?\;}`,
 o:[R`2^{h+1}-1`,R`2^h-1`,R`2^h`,R`h+1`],om:1,a:0,
 why:R`Level i holds at most \(2^i\) nodes: \(1+2+\dots+2^h=2^{h+1}-1\). The minimum is \(h+1\), a chain. Check whether a question counts height in nodes or edges.`},
{id:'minheight',t:'ds',u:'tree',lv:2,k:'nat',name:'Minimum height for n nodes',sheet:R`h_{\min}=\lceil\log_2(n+1)\rceil-1`,
 q:R`What is the minimum possible height of a binary tree with 100 nodes (a single node has height 0)?`,n:{v:6},
 why:R`Height 5 holds at most 63 nodes and height 6 holds 127, so 100 nodes need height 6.`},
{id:'nulls',t:'ds',u:'tree',lv:1,k:'nat',name:'Null pointers in a binary tree',sheet:R`n\ \text{nodes}:\ 2n\ \text{child fields},\ n-1\ \text{used},\ n+1\ \text{null}`,
 q:R`A binary tree with 10 nodes is stored with left and right pointers. How many of these pointers are null?`,n:{v:11},
 why:R`20 pointer fields; each of the \(n-1=9\) edges uses one, leaving 11 null.`},
{id:'exprpost',t:'ds',u:'tree',lv:1,k:'mcq',name:'Traversals of an expression tree',sheet:R`\text{pre: root L R;\ in: L root R;\ post: L R root}`,
 q:R`The expression tree for \((a+b)\cdot(c-d)\) is traversed in postorder. The result is:`,
 o:[R`<code>a b + c d - *</code>`,R`<code>* + a b - c d</code>`,R`<code>a + b * c - d</code>`,R`<code>a b c d + - *</code>`],a:0,
 why:R`Postorder visits both subtrees before the root, giving postfix notation. Preorder gives prefix (<code>* + a b - c d</code>), and inorder gives the infix form without brackets.`},
{id:'rebuild',t:'ds',u:'tree',lv:2,k:'mcq',name:'Rebuilding a tree from traversals',sheet:R`\text{preorder gives the root; inorder splits left and right subtrees}`,
 q:R`A binary tree has preorder A B D E C F and inorder D B E A F C. Its postorder is:`,
 o:[R`D E B F C A`,R`D E B C F A`,R`E D B F C A`,R`D B E F C A`],a:0,
 why:R`A is the root; inorder puts D B E on the left (root B, children D and E) and F C on the right (root C, with F as its left child). Postorder: D E B, F C, A.`},
{id:'uniq',t:'ds',u:'tree',lv:2,k:'cond',name:'Which traversals fix the tree',sheet:R`\text{inorder + (pre or post or level) is unique; pre + post is unique only for full trees}`,
 q:R`A binary tree with distinct labels is uniquely determined by:`,
 o:[R`Inorder together with preorder (or postorder)`,R`Preorder together with postorder, for any binary tree`,R`Preorder alone`,R`Inorder alone`],a:0,
 why:R`Without inorder you can't tell a lone left child from a lone right child. Preorder with postorder works only when every node has 0 or 2 children.`},
{id:'arrayidx',t:'ds',u:'tree',lv:1,k:'fill',name:'Array storage of a complete tree',sheet:R`\text{0-based: children }2i+1,\ 2i+2;\ \text{parent }\lfloor(i-1)/2\rfloor`,
 q:R`A complete binary tree is stored in an array starting at index 0. The left child of index i is at:`,f:R`\text{left}(i)=\boxed{\;?\;}`,
 o:[R`2i+1`,R`2i`,R`2i+2`,R`\lfloor i/2\rfloor`],om:1,a:0,
 why:R`With 1-based indexing it is 2i and 2i + 1, with parent \(\lfloor i/2\rfloor\). Watch which convention a question uses.`},
{id:'shapes',t:'ds',u:'tree',lv:2,k:'nat',name:'Number of binary tree shapes',sheet:R`\#\text{shapes with }n\text{ nodes}=C_n=\frac{1}{n+1}\binom{2n}{n}`,
 q:R`How many differently shaped binary trees have exactly 3 nodes?`,n:{v:5},
 why:R`\(C_3=5\): two zig-zags, two straight chains and one balanced tree.`},
{id:'bstin',t:'ds',u:'bst',lv:1,k:'mcq',name:'Inorder of a BST',sheet:R`\text{inorder traversal of a BST lists keys in increasing order}`,
 q:R`Which traversal of a binary search tree lists the keys in sorted order?`,
 o:[R`Inorder`,R`Preorder`,R`Postorder`,R`Level order`],a:0,
 why:R`Left subtree keys are smaller and right subtree keys are larger, so left–root–right gives ascending order.`},
{id:'bstins',t:'ds',u:'bst',lv:2,k:'mcq',name:'BST insertion',sheet:R`\text{insert: go left if smaller, right if larger, attach at the empty spot}`,
 q:R`Insert 50, 30, 70, 20, 40, 60, 80, 35 in that order into an empty BST. What is the parent of 35?`,
 o:[R`40`,R`30`,R`20`,R`60`],a:0,
 why:R`35 is less than 50, so go left to 30; greater than 30, so go right to 40; less than 40, so it becomes the left child of 40.`},
{id:'bstworst',t:'ds',u:'bst',lv:1,k:'mcq',name:'BST search cost',sheet:R`\text{search }O(h);\ h=O(\log n)\ \text{balanced},\ h=n-1\ \text{worst}`,
 q:R`Keys 1, 2, …, n are inserted in increasing order into an empty BST. Searching then takes, in the worst case:`,
 o:[R`\(O(n)\)`,R`\(O(\log n)\)`,R`\(O(1)\)`,R`\(O(n\log n)\)`],a:0,
 why:R`Sorted insertions build a chain of height \(n-1\). Self-balancing trees (AVL, red–black) keep the height \(O(\log n)\).`},
{id:'bstdel',t:'ds',u:'bst',lv:2,k:'mcq',name:'Deleting a node with two children',sheet:R`\text{replace with inorder successor (min of right subtree) or predecessor}`,
 q:R`To delete a BST node with two children, its key is replaced by:`,
 o:[R`Its inorder successor (smallest key in the right subtree)`,R`Its left child`,R`The root's key`,R`The largest key in the right subtree`],a:0,
 why:R`The successor keeps the BST order and has no left child, so removing it from its old spot is easy. The inorder predecessor (largest key in the left subtree) works too.`},
{id:'bstcount',t:'ds',u:'bst',lv:2,k:'nat',name:'Number of BSTs on n keys',sheet:R`\#\text{BSTs on }n\text{ distinct keys}=C_n`,
 q:R`How many structurally different BSTs can hold the keys 1, 2, 3, 4?`,n:{v:14},
 why:R`Choosing root k leaves \(k-1\) keys on the left and \(4-k\) on the right: \(C_0C_3+C_1C_2+C_2C_1+C_3C_0=5+2+2+5=14\).`},
{id:'bstpre',t:'ds',u:'bst',lv:3,k:'mcq',name:'BST from a preorder sequence',sheet:R`\text{preorder of a BST: root, then all smaller keys, then all larger keys}`,
 q:R`Which sequence can NOT be the preorder traversal of a BST?`,
 o:[R`10, 5, 12, 7, 15`,R`10, 5, 3, 7, 15`,R`10, 15, 12, 20`,R`5, 3, 4, 8, 9`],a:0,
 why:R`After 10 and 5, the 12 starts the right subtree of 10. Every key after it must then exceed 10, but 7 doesn't.`},
{id:'loadf',t:'ds',u:'hash',lv:1,k:'fill',name:'Load factor',sheet:R`\alpha=\frac{n}{m}\ \ (n\ \text{keys},\ m\ \text{slots})`,
 f:R`\alpha=\frac{\boxed{\;?\;}}{m}`,
 o:[R`n`,R`m-n`,R`1`,R`n^2`],om:1,a:0,
 why:R`Average keys per slot. With chaining α can exceed 1; with open addressing \(\alpha\le1\).`},
{id:'chain',t:'ds',u:'hash',lv:1,k:'mcq',name:'Chaining costs',sheet:R`\text{chaining, simple uniform hashing: expected search }\Theta(1+\alpha);\ \text{worst }\Theta(n)`,
 q:R`A hash table with chaining stores n keys. The worst-case search time is:`,
 o:[R`\(\Theta(n)\), when all keys land in one chain`,R`\(\Theta(1)\)`,R`\(\Theta(\log n)\)`,R`\(\Theta(1+\alpha)\)`],a:0,
 why:R`\(\Theta(1+\alpha)\) is the expected time under simple uniform hashing. An adversary can still force every key into one slot.`},
{id:'probes',t:'ds',u:'hash',lv:2,k:'fill',name:'Open addressing probes',sheet:R`\text{unsuccessful}\le\frac{1}{1-\alpha},\ \ \text{successful}\le\frac{1}{\alpha}\ln\frac{1}{1-\alpha}`,
 q:R`Under uniform hashing with load factor \(\alpha\lt1\), the expected number of probes in an unsuccessful search is at most:`,f:R`\boxed{\;?\;}`,
 o:[R`\frac{1}{1-\alpha}`,R`1+\alpha`,R`\frac{1}{\alpha}`,R`\frac{1}{\alpha}\ln\frac{1}{1-\alpha}`],om:1,a:0,
 why:R`Each probe hits an occupied slot with probability about α, giving a geometric series \(1+\alpha+\alpha^2+\dots\). An insertion costs the same as an unsuccessful search.`},
{id:'linprobe',t:'ds',u:'hash',lv:2,k:'nat',name:'Linear probing',sheet:R`h_i(k)=(h(k)+i)\bmod m`,
 q:R`Table size 7, \(h(k)=k\bmod7\), linear probing. Keys 10, 17, 3, 24 are inserted in that order. At which index does 24 end up?`,n:{v:6},
 why:R`10 → 3; 17 → 3 taken, so 4; 3 → 3, 4 taken, so 5; 24 → 3, 4, 5 taken, so 6. Long runs like this are primary clustering.`},
{id:'dblhash',t:'ds',u:'hash',lv:2,k:'fill',name:'Double hashing',sheet:R`h_i(k)=\big(h_1(k)+i\,h_2(k)\big)\bmod m,\ \ h_2(k)\ne0`,
 f:R`h_i(k)=\big(h_1(k)+\boxed{\;?\;}\big)\bmod m`,
 o:[R`i\,h_2(k)`,R`i`,R`i^2`,R`h_2(k)`],om:1,a:0,
 why:R`The step size depends on the key, which avoids clustering. \(h_2\) must never be 0 and should be coprime with m so every slot can be reached.`},
{id:'clust',t:'ds',u:'hash',lv:1,k:'mcq',name:'Primary clustering',sheet:R`\text{linear probing: primary clustering; quadratic: secondary clustering}`,
 q:R`Long runs of occupied slots that keep growing are a weakness of:`,
 o:[R`Linear probing`,R`Separate chaining`,R`Double hashing`,R`A perfect hash function`],a:0,
 why:R`Any key hashing into a run extends it, so runs grow faster and faster. Quadratic probing reduces this; double hashing mostly removes it.`},
{id:'collexp',t:'ds',u:'hash',lv:2,k:'nat',name:'Expected number of collisions',sheet:R`E[\#\text{colliding pairs}]=\binom n2\frac1m`,
 q:R`10 keys are hashed uniformly and independently into 20 slots. What is the expected number of pairs of keys that collide?`,n:{v:2.25},
 why:R`Each of the \(\binom{10}{2}=45\) pairs collides with probability \(\tfrac1{20}\). By linearity, \(45/20=2.25\).`},

/* ---------- Searching ---------- */
{id:'linavg',t:'search',u:'linsearch',lv:1,k:'fill',name:'Linear search comparisons',sheet:R`\text{worst }n,\ \ \text{average (successful, uniform)}\ \frac{n+1}{2}`,
 q:R`The key is equally likely to be at any of the n positions. Average comparisons for a successful linear search:`,f:R`\boxed{\;?\;}`,
 o:[R`\frac{n+1}{2}`,R`\frac n2`,R`\log_2n`,R`n`],om:1,a:0,
 why:R`Position i costs i comparisons: \(\frac1n\sum i=\frac{n+1}{2}\). An unsuccessful search costs n.`},
{id:'linnat',t:'search',u:'linsearch',lv:1,k:'nat',name:'Linear search in numbers',sheet:R`\text{average successful}=\frac{n+1}{2}`,
 q:R`An unsorted array has 99 distinct elements, and the key is present at a uniformly random position. Expected number of comparisons for linear search?`,n:{v:50},
 why:R`\((99+1)/2=50\).`},
{id:'binreq',t:'search',u:'binsearch',lv:1,k:'mcq',name:'When binary search is O(log n)',sheet:R`\text{needs sorted data and }O(1)\ \text{random access}`,
 q:R`Binary search takes \(O(\log n)\) worst-case time on:`,
 o:[R`A sorted array`,R`A sorted singly linked list`,R`An unsorted array`,R`Any linked list`],a:0,
 why:R`Jumping to the middle needs random access. On a linked list, reaching the middle alone costs \(O(n)\).`},
{id:'bincmp',t:'search',u:'binsearch',lv:2,k:'nat',name:'Maximum binary search comparisons',sheet:R`\text{max comparisons}=\lfloor\log_2n\rfloor+1`,
 q:R`Binary search on a sorted array of 500 elements. Each step compares the middle element with the key (one three-way comparison). What is the maximum number of comparisons?`,n:{v:9},
 why:R`\(\lfloor\log_2500\rfloor+1=8+1=9\). Each comparison at least halves the remaining range.`},
{id:'binrec',t:'search',u:'binsearch',lv:1,k:'fill',name:'Binary search recurrence',sheet:R`T(n)=T(n/2)+c\Rightarrow T(n)=\Theta(\log n)`,
 f:R`T(n)=\boxed{\;?\;}+c`,
 o:[R`T(n/2)`,R`2T(n/2)`,R`T(n-1)`,R`T(n/2)+T(n/4)`],om:1,a:0,
 why:R`Only one half is searched after each comparison. \(2T(n/2)+c\) would visit both halves and cost \(\Theta(n)\).`},
{id:'bintrace',t:'search',u:'binsearch',lv:2,k:'nat',name:'Tracing binary search',sheet:R`\text{mid}=\lfloor(\text{lo}+\text{hi})/2\rfloor`,
 q:R`Search for 57 in [3, 8, 15, 21, 30, 42, 57, 63, 77] (indices 0–8) with \(\text{mid}=\lfloor(\text{lo}+\text{hi})/2\rfloor\). How many array elements are compared with 57?`,n:{v:2},
 why:R`mid = 4 (30): go right, lo = 5. mid = 6 (57): found. Two comparisons.`},

/* ---------- Sorting ---------- */
{id:'bestcase',t:'sort',u:'elemsort',lv:1,k:'mcq',name:'Best cases of the simple sorts',sheet:R`\text{insertion }O(n)\ \text{on sorted input; selection }\Theta(n^2)\ \text{always}`,
 q:R`Which sort runs in \(O(n)\) time on an already sorted array?`,
 o:[R`Insertion sort`,R`Selection sort`,R`Merge sort`,R`Quick sort with the last element as pivot`],a:0,
 why:R`Each new element is compared once and stays put. Selection sort still scans the rest each pass, and last-pivot quick sort hits its \(O(n^2)\) worst case.`},
{id:'swapsmin',t:'sort',u:'elemsort',lv:1,k:'mcq',name:'Fewest swaps',sheet:R`\text{selection sort: at most }n-1\ \text{swaps}`,
 q:R`Which sort does at most \(n-1\) swaps on any input?`,
 o:[R`Selection sort`,R`Bubble sort`,R`Insertion sort`,R`Quick sort`],a:0,
 why:R`Each pass swaps the minimum into place once. Bubble and insertion sort swap once per inversion, up to \(n(n-1)/2\).`},
{id:'invers',t:'sort',u:'elemsort',lv:2,k:'nat',name:'Inversions and insertion sort',sheet:R`\#\text{shifts in insertion sort}=\#\text{inversions}`,
 q:R`How many element shifts (adjacent swaps) does insertion sort make on [3, 1, 4, 2, 5]?`,n:{v:3},
 why:R`Count inversions, pairs out of order: (3, 1), (3, 2), (4, 2). Bubble sort makes the same number of swaps.`},
{id:'bubpass',t:'sort',u:'elemsort',lv:1,k:'mcq',name:'One pass of bubble sort',sheet:R`\text{each pass bubbles the largest remaining element to the end}`,
 q:R`After the first pass of bubble sort (ascending) on [5, 1, 4, 2, 8], the array is:`,
 o:[R`[1, 4, 2, 5, 8]`,R`[1, 2, 4, 5, 8]`,R`[1, 5, 4, 2, 8]`,R`[5, 1, 4, 2, 8]`],a:0,
 why:R`5 swaps past 1, 4 and 2, then stops before 8. Only the largest element is guaranteed in place after one pass.`},
{id:'stable',t:'sort',u:'elemsort',lv:2,k:'mcq',name:'Stable sorting',sheet:R`\text{stable: insertion, bubble, merge;\ not stable (usual versions): selection, quick}`,
 q:R`Which of these, in its usual array implementation, is NOT stable?`,
 o:[R`Selection sort`,R`Insertion sort`,R`Bubble sort`,R`Merge sort`],a:0,
 why:R`Swapping the minimum into place can jump an element past an equal one, e.g. [2a, 2b, 1] becomes [1, 2b, 2a].`},
{id:'bubcmp',t:'sort',u:'elemsort',lv:1,k:'nat',name:'Comparisons in bubble sort',sheet:R`\text{without early exit}:\ \frac{n(n-1)}{2}\ \text{comparisons}`,
 q:R`Plain bubble sort (no early-exit check) on 6 elements makes how many comparisons?`,n:{v:15},
 why:R`\(5+4+3+2+1=15=\frac{6\cdot5}{2}\), whatever the input order.`},
{id:'inssorted',t:'sort',u:'elemsort',lv:1,k:'nat',name:'Insertion sort on sorted input',sheet:R`\text{sorted input: }n-1\ \text{comparisons}`,
 q:R`Insertion sort on an already sorted array of 10 elements makes how many comparisons?`,n:{v:9},
 why:R`Each of elements 2 to 10 is compared once with its left neighbour and stays.`},
{id:'mergerec',t:'sort',u:'merge',lv:1,k:'fill',name:'Merge sort recurrence',sheet:R`T(n)=2T(n/2)+\Theta(n)\Rightarrow\Theta(n\log n)\ \text{in every case}`,
 f:R`T(n)=2T(n/2)+\boxed{\;?\;}`,
 o:[R`\Theta(n)`,R`\Theta(1)`,R`\Theta(\log n)`,R`\Theta(n^2)`],om:1,a:0,
 why:R`Merging two halves is linear. The result is \(\Theta(n\log n)\) for best, average and worst cases, using \(O(n)\) extra space.`},
{id:'mergecmp',t:'sort',u:'merge',lv:2,k:'nat',name:'Comparisons to merge two lists',sheet:R`\text{merge sizes }m,n:\ \text{worst }m+n-1,\ \text{best }\min(m,n)`,
 q:R`Two sorted lists of sizes 5 and 7 are merged. What is the maximum number of comparisons?`,n:{v:11},
 why:R`Each comparison outputs one element, and the last element needs none: \(5+7-1=11\).`},
{id:'mergeprop',t:'sort',u:'merge',lv:1,k:'mcq',name:'Merge sort properties',sheet:R`\text{merge sort: stable, }O(n)\ \text{extra space, not in place}`,
 q:R`Which is true of standard merge sort on arrays?`,
 o:[R`It is stable but needs \(O(n)\) extra space`,R`It is in place and stable`,R`Its worst case is \(O(n^2)\)`,R`It is not stable`],a:0,
 why:R`Taking from the left half on ties keeps it stable. Merging needs a temporary array.`},
{id:'mergepass',t:'sort',u:'merge',lv:1,k:'nat',name:'Passes of bottom-up merge sort',sheet:R`\lceil\log_2n\rceil\ \text{passes}`,
 q:R`Bottom-up merge sort on 32 elements merges runs of size 1, 2, 4, … How many merge passes does it make?`,n:{v:5},
 why:R`Run sizes double each pass: \(1\to2\to4\to8\to16\to32\), which is \(\log_232=5\) passes.`},
{id:'qworst',t:'sort',u:'quick',lv:1,k:'mcq',name:'Quick sort worst case',sheet:R`\text{pivot always min or max}\Rightarrow T(n)=T(n-1)+\Theta(n)=\Theta(n^2)`,
 q:R`Quick sort with the first element as pivot is slowest on:`,
 o:[R`An already sorted array`,R`A randomly shuffled array`,R`An array with distinct elements in random order`,R`An array of size 1`],a:0,
 why:R`Every partition is as lopsided as possible (0 and n − 1), giving \(\Theta(n^2)\). A random pivot makes this unlikely for any input.`},
{id:'qrec',t:'sort',u:'quick',lv:2,k:'bug',name:'Quick sort recurrences',sheet:R`\text{best/balanced}: 2T(n/2)+n;\ \text{worst}: T(n-1)+n;\ \text{expected}: \Theta(n\log n)`,
 q:R`This is meant to be quick sort's worst-case recurrence. Find the mistake.`,f:R`T(n)=2T(n-1)+\Theta(n)`,
 o:[R`It should be \(T(n-1)+\Theta(n)\): only one side is non-empty`,R`It should be \(T(n/2)+\Theta(n)\)`,R`The \(\Theta(n)\) should be \(\Theta(1)\)`,R`Nothing, it is correct`],a:0,
 why:R`The worst split is 0 and n − 1, so there is one recursive call of size n − 1, plus linear partitioning: \(\Theta(n^2)\). \(2T(n-1)\) would be exponential.`},
{id:'lomuto',t:'sort',u:'quick',lv:2,k:'nat',name:'Lomuto partition',sheet:R`\text{pivot = last; elements }\le\text{pivot move left; pivot lands at its sorted index}`,
 q:R`Lomuto partition with the last element as pivot is applied to [7, 2, 9, 4, 5] (indices 0–4). At which index does the pivot end up?`,n:{v:2},
 why:R`Two elements (2 and 4) are smaller than 5, so the pivot lands at index 2, its final sorted position.`},
{id:'qprops',t:'sort',u:'quick',lv:1,k:'mcq',name:'Quick sort properties',sheet:R`\text{in place, not stable, expected }O(n\log n),\ \text{worst }O(n^2)`,
 q:R`Which statement about standard quick sort is true?`,
 o:[R`It sorts in place but is not stable`,R`It is stable and needs \(O(n)\) extra space`,R`Its worst case is \(O(n\log n)\)`,R`It always beats merge sort`],a:0,
 why:R`Partitioning swaps elements across the array, which breaks stability. The recursion stack is \(O(\log n)\) expected, \(O(n)\) worst.`},
{id:'qrand',t:'sort',u:'quick',lv:2,k:'cond',name:'Randomised quick sort',sheet:R`\text{random pivot}\Rightarrow E[T(n)]=O(n\log n)\ \text{for every input}`,
 q:R`Quick sort runs in expected \(O(n\log n)\) time on every input when:`,
 o:[R`The pivot is chosen uniformly at random`,R`The first element is the pivot`,R`The array has distinct elements`,R`The array is already sorted`],a:0,
 why:R`With a fixed pivot rule, some input is always bad. Randomising moves the averaging from the input to the algorithm's own coin flips.`},

/* ---------- Graphs ---------- */
{id:'hand',t:'graph',u:'gbasics',lv:1,k:'nat',name:'Handshake lemma',sheet:R`\sum_v\deg(v)=2|E|`,
 q:R`A simple graph has 10 vertices, each of degree 3. How many edges does it have?`,n:{v:15},
 why:R`\(10\times3=30=2|E|\). This also shows the number of odd-degree vertices is always even.`},
{id:'maxedges',t:'graph',u:'gbasics',lv:1,k:'fill',name:'Maximum edges',sheet:R`\text{simple undirected: }\binom n2=\frac{n(n-1)}{2};\ \text{directed: }n(n-1)`,
 q:R`A simple undirected graph on n vertices has at most:`,f:R`|E|_{\max}=\boxed{\;?\;}`,
 o:[R`\frac{n(n-1)}{2}`,R`n(n-1)`,R`n^2`,R`n-1`],om:1,a:0,
 why:R`One edge per unordered pair of vertices. Directed graphs without self-loops allow both directions: \(n(n-1)\).`},
{id:'disconn',t:'graph',u:'gbasics',lv:2,k:'nat',name:'Most edges in a disconnected graph',sheet:R`\text{disconnected on }n\text{ vertices}:\ |E|\le\binom{n-1}{2}`,
 q:R`A simple undirected graph on 8 vertices is disconnected. What is the maximum number of edges it can have?`,n:{v:21},
 why:R`Make 7 vertices a complete graph and leave one isolated: \(\binom72=21\).`},
{id:'repr',t:'graph',u:'gbasics',lv:1,k:'mcq',name:'Adjacency matrix vs list',sheet:R`\text{matrix: }\Theta(V^2)\ \text{space, }O(1)\ \text{edge test; list: }\Theta(V+E)\ \text{space}`,
 q:R`For a sparse graph, why is an adjacency list usually preferred over an adjacency matrix?`,
 o:[R`It uses \(\Theta(V+E)\) space instead of \(\Theta(V^2)\)`,R`It answers "is (u, v) an edge?" in \(O(1)\)`,R`It allows weighted edges`,R`It makes BFS \(O(V^2)\)`],a:0,
 why:R`The matrix wins on the \(O(1)\) edge test; the list wins on space and on traversal time, \(O(V+E)\) against \(O(V^2)\).`},
{id:'forest',t:'graph',u:'gbasics',lv:2,k:'nat',name:'Edges of a forest',sheet:R`\text{forest with }n\text{ vertices and }k\text{ trees has }n-k\text{ edges}`,
 q:R`DFS on an undirected graph with 50 vertices produces a forest with 44 tree edges. How many connected components does the graph have?`,n:{v:6},
 why:R`Each component gives one tree with (vertices − 1) edges, so edges \(=n-k\): \(k=50-44=6\).`},
{id:'adjpow',t:'graph',u:'gbasics',lv:3,k:'mcq',name:'Powers of the adjacency matrix',sheet:R`(A^k)_{ij}=\#\text{walks of length }k;\ (A^2)_{ii}=\deg(i);\ \operatorname{tr}(A^3)=6\,\#\triangle`,
 q:R`A is the adjacency matrix of a simple undirected graph. Which statement is true?`,
 o:[R`The diagonal entries of \(A^2\) are the vertex degrees`,R`\(A^2\) has all zero diagonal entries`,R`\(\operatorname{tr}(A^3)\) equals the number of triangles`,R`\(A^2=A\)`],a:0,
 why:R`\((A^2)_{ii}\) counts walks i → j → i, one per neighbour. \(\operatorname{tr}(A^3)\) counts each triangle 6 times (3 starting points × 2 directions).`},
{id:'bfsds',t:'graph',u:'bfs',lv:1,k:'mcq',name:'BFS essentials',sheet:R`\text{BFS: queue, }O(V+E)\ \text{with adjacency lists}`,
 q:R`BFS on a graph stored as adjacency lists runs in:`,
 o:[R`\(O(V+E)\) using a queue`,R`\(O(V+E)\) using a stack`,R`\(O(V\log V)\) using a heap`,R`\(O(V^2)\) using a queue`],a:0,
 why:R`Each vertex is enqueued once and each adjacency list scanned once. With an adjacency matrix it becomes \(O(V^2)\).`},
{id:'bfssp',t:'graph',u:'bfs',lv:1,k:'cond',name:'BFS gives shortest paths',sheet:R`\text{BFS from }s\text{ finds fewest-edge paths in unweighted graphs}`,
 q:R`BFS from s finds shortest paths from s when:`,
 o:[R`The graph is unweighted (or all edges have equal weight)`,R`Edge weights are non-negative`,R`The graph is a DAG`,R`Always, for any weights`],a:0,
 why:R`BFS visits vertices in order of their edge count from s. With unequal weights you need Dijkstra (non-negative) or Bellman–Ford.`},
{id:'bfsorder',t:'graph',u:'bfs',lv:2,k:'mcq',name:'Tracing BFS',sheet:R`\text{visit all neighbours of the front vertex before going deeper}`,
 q:R`Undirected edges: A–B, A–C, B–D, C–D, C–E, D–F. Neighbours are processed alphabetically. BFS from A visits vertices in the order:`,
 o:[R`A B C D E F`,R`A B D C E F`,R`A B C E D F`,R`A C B D E F`],a:0,
 why:R`Queue: A → add B, C. B → add D. C → add E (D already seen). D → add F. Order A B C D E F. A B D C E F is the DFS order.`},
{id:'bfslevels',t:'graph',u:'bfs',lv:3,k:'mcq',name:'Non-tree edges in BFS',sheet:R`\text{undirected BFS: every edge joins levels differing by at most 1}`,
 q:R`BFS on a connected undirected graph assigns each vertex a level (its distance from the start). A non-tree edge (u, v) always satisfies:`,
 o:[R`\(|\text{level}(u)-\text{level}(v)|\le1\)`,R`\(\text{level}(u)=\text{level}(v)\)`,R`\(|\text{level}(u)-\text{level}(v)|=2\)`,R`It joins a vertex to its own ancestor`],a:0,
 why:R`If an edge jumped two levels, BFS would have reached the deeper vertex earlier through it. Same-level edges are what make a graph non-bipartite.`},
{id:'dfsorder',t:'graph',u:'dfs',lv:2,k:'mcq',name:'Tracing DFS',sheet:R`\text{go as deep as possible, backtrack when stuck}`,
 q:R`Undirected edges: A–B, A–C, B–D, C–D, C–E, D–F. Neighbours are processed alphabetically. DFS from A visits vertices in the order:`,
 o:[R`A B D C E F`,R`A B C D E F`,R`A C E D F B`,R`A B D F C E`],a:0,
 why:R`A → B → D → C (D's first unvisited neighbour) → E. Back up to D → F.`},
{id:'dfsedge',t:'graph',u:'dfs',lv:2,k:'mcq',name:'DFS edge types (undirected)',sheet:R`\text{undirected DFS: only tree and back edges}`,
 q:R`DFS on an undirected graph classifies every edge as:`,
 o:[R`A tree edge or a back edge`,R`A tree, back, forward or cross edge`,R`A tree edge or a cross edge`,R`Only tree edges`],a:0,
 why:R`A cross edge would mean DFS left a neighbour unexplored. Forward and cross edges appear only in directed graphs.`},
{id:'cyc',t:'graph',u:'dfs',lv:2,k:'cond',name:'Cycle detection',sheet:R`\text{directed graph has a cycle}\iff\text{DFS finds a back edge}`,
 q:R`A directed graph has a cycle exactly when DFS finds:`,
 o:[R`A back edge`,R`A cross edge`,R`A forward edge`,R`More than one DFS tree`],a:0,
 why:R`A back edge goes to an ancestor still on the recursion stack, closing a cycle. With no back edges, reverse finishing order is a topological order.`},
{id:'topo',t:'graph',u:'dfs',lv:1,k:'mcq',name:'Topological sort',sheet:R`\text{exists}\iff\text{DAG};\ \text{reverse DFS finishing order}`,
 q:R`A topological ordering of a directed graph exists exactly when the graph:`,
 o:[R`Has no directed cycle`,R`Is strongly connected`,R`Is a tree`,R`Has no vertex of in-degree 0`],a:0,
 why:R`In a cycle every vertex would have to come before itself. Every DAG has at least one source, which starts the order.`},
{id:'topocount',t:'graph',u:'dfs',lv:2,k:'nat',name:'Counting topological orders',sheet:R`\text{count linear orders that respect every edge}`,
 q:R`A DAG has edges A→B, A→C, B→D, C→D, C→E. How many topological orders does it have?`,n:{v:5},
 why:R`A must come first. After it, D needs both B and C before it, and E needs C. The valid orders are A B C D E, A B C E D, A C B D E, A C B E D and A C E B D.`},
{id:'reach',t:'graph',u:'dfs',lv:2,k:'mcq',name:'Reachability in the reversed graph',sheet:R`u\ \text{reachable from }v\text{ in }G\iff v\ \text{reachable from }u\text{ in }G^R`,
 q:R`\(G^R\) is G with every edge reversed. If u is reachable from v in G, then:`,
 o:[R`v is reachable from u in \(G^R\)`,R`u is reachable from v in \(G^R\)`,R`BFS of \(G^R\) from v visits the same set as DFS of G from v`,R`G is strongly connected`],a:0,
 why:R`Reverse the path v ⇝ u edge by edge. This is the key step in Kosaraju's strongly-connected-components algorithm.`},
{id:'dijneg',t:'graph',u:'sp',lv:1,k:'cond',name:'Dijkstra’s requirement',sheet:R`\text{Dijkstra: correct iff all edge weights}\ge0`,
 q:R`Dijkstra's algorithm is guaranteed to give correct shortest paths when:`,
 o:[R`All edge weights are non-negative`,R`The graph has no cycles`,R`The graph is undirected`,R`Weights are integers`],a:0,
 why:R`Dijkstra finalises the closest unvisited vertex, assuming no later path can be shorter. A negative edge breaks that; use Bellman–Ford.`},
{id:'dijcost',t:'graph',u:'sp',lv:2,k:'mcq',name:'Shortest-path algorithm costs',sheet:R`\text{Dijkstra (binary heap) }O((V+E)\log V);\ \text{Bellman–Ford }O(VE);\ \text{Floyd–Warshall }O(V^3)`,
 q:R`Which pairing of algorithm and running time is correct?`,
 o:[R`Bellman–Ford: \(O(VE)\)`,R`Dijkstra with a binary heap: \(O(V^3)\)`,R`Floyd–Warshall: \(O(V+E)\)`,R`BFS: \(O(VE)\)`],a:0,
 why:R`Bellman–Ford relaxes every edge V − 1 times; one more round detects negative cycles. Floyd–Warshall is all-pairs, \(O(V^3)\).`},
{id:'dijnat',t:'graph',u:'sp',lv:2,k:'nat',name:'Running Dijkstra',sheet:R`d[v]\leftarrow\min\big(d[v],\ d[u]+w(u,v)\big)`,
 q:R`Directed edges with weights: S→A 4, S→B 1, B→A 2, A→C 1, B→C 5. Find the shortest distance from S to C.`,n:{v:4},
 why:R`S→B (1) → A (3) → C (4) beats S→A→C (5) and S→B→C (6). The direct S→A edge isn't the best way to A.`},
{id:'addconst',t:'graph',u:'sp',lv:3,k:'mcq',name:'Changing all edge weights',sheet:R`\text{adding }c\text{ to every edge favours paths with fewer edges; scaling by }c>0\text{ keeps them}`,
 q:R`A positive constant is added to every edge weight of a graph. Which statement is always true?`,
 o:[R`Shortest paths may change, because paths with more edges gain more`,R`Shortest paths never change`,R`Every shortest path gets longer by the same amount`,R`Dijkstra stops working`],a:0,
 why:R`A path with k edges grows by kc. Multiplying all weights by a positive constant, by contrast, keeps every shortest path. The minimum spanning tree stays the same in both cases.`},
{id:'bellneg',t:'graph',u:'sp',lv:2,k:'mcq',name:'Negative cycles',sheet:R`\text{Bellman–Ford: an extra relaxation round that still improves}\Rightarrow\text{negative cycle}`,
 q:R`Which algorithm can report that a graph contains a negative-weight cycle reachable from the source?`,
 o:[R`Bellman–Ford`,R`Dijkstra`,R`BFS`,R`DFS-based topological sort`],a:0,
 why:R`After V − 1 rounds all shortest paths are final. If round V still lowers a distance, some cycle has negative total weight, and shortest paths are undefined.`},

/* ---------- Complexity ---------- */
{id:'bigo',t:'cx',u:'asym',lv:1,k:'fill',name:'Big-O definition',sheet:R`f=O(g)\iff\exists c>0,n_0:\ f(n)\le c\,g(n)\ \ \forall n\ge n_0`,
 f:R`f=O(g)\iff\exists c,n_0:\ f(n)\le\boxed{\;?\;}\ \ \forall n\ge n_0`,
 o:[R`c\,g(n)`,R`g(n)+c`,R`g(c\,n)`,R`c^{\,g(n)}`],om:1,a:0,
 why:R`An upper bound up to a constant factor, for large n. \(\Omega\) flips the inequality, and \(\Theta\) needs both.`},
{id:'growth',t:'cx',u:'asym',lv:2,k:'mcq',name:'Growth-rate ordering',sheet:R`\log n\ll\sqrt n\ll n\ll n\log n\ll n^2\ll n^{\log n}\ll2^n\ll n!`,
 q:R`Which function grows fastest?`,
 o:[R`\(n!\)`,R`\(2^n\)`,R`\(n^{100}\)`,R`\(n^{\log n}\)`],a:0,
 why:R`\(n^{\log n}=2^{(\log n)^2}\) is slower than \(2^n\), and \(n!\approx(n/e)^n\) beats \(2^n\). Compare logs when unsure.`},
{id:'theta',t:'cx',u:'asym',lv:1,k:'mcq',name:'Θ notation',sheet:R`f=\Theta(g)\iff f=O(g)\ \text{and}\ f=\Omega(g)`,
 q:R`\(f(n)=\Theta(g(n))\) means:`,
 o:[R`f is bounded above and below by constant multiples of g for large n`,R`f is bounded above by g`,R`\(f(n)=g(n)\) for large n`,R`f grows strictly slower than g`],a:0,
 why:R`\(3n^2+5n=\Theta(n^2)\). "Strictly slower" is little-o.`},
{id:'doubling',t:'cx',u:'asym',lv:2,k:'mcq',name:'Loop with a doubling index',sheet:R`\sum_{i=1,2,4,\dots\lt n}i\lt2n=O(n)`,
 q:R`What is the running time?<pre><code>i = 1
while i &lt; n:
    for j in range(i):
        work()      # O(1)
    i *= 2</code></pre>`,
 o:[R`\(O(n)\)`,R`\(O(n\log n)\)`,R`\(O(\log n)\)`,R`\(O(n^2)\)`],a:0,
 why:R`The inner loop runs \(1+2+4+\dots\) times, a geometric sum below 2n. Multiplying the \(\log n\) outer passes by the largest inner count, n, overestimates it.`},
{id:'logfact',t:'cx',u:'asym',lv:2,k:'mcq',name:'log n!',sheet:R`\log(n!)=\Theta(n\log n)`,
 q:R`\(\log(n!)\) is:`,
 o:[R`\(\Theta(n\log n)\)`,R`\(\Theta(n)\)`,R`\(\Theta(\log n)\)`,R`\(\Theta(n^2)\)`],a:0,
 why:R`\(\log n!=\sum\log k\le n\log n\), and the top half of the terms are each at least \(\log(n/2)\). This is also why comparison sorting needs \(\Omega(n\log n)\) comparisons.`},
{id:'master',t:'cx',u:'recur',lv:2,k:'fill',name:'Master theorem',sheet:R`T(n)=aT(n/b)+f(n):\ \text{compare }f(n)\text{ with }n^{\log_ba}`,
 q:R`For \(T(n)=aT(n/b)+f(n)\), the master theorem compares f(n) with:`,f:R`n^{\boxed{\;?\;}}`,
 o:[R`\log_b a`,R`\log_a b`,R`a/b`,R`b`],om:1,a:0,
 why:R`\(n^{\log_ba}\) is the total cost of the leaves. If f is polynomially smaller, the leaves dominate; equal gives an extra \(\log n\); larger (with regularity) gives \(\Theta(f)\).`},
{id:'master4',t:'cx',u:'recur',lv:2,k:'mcq',name:'Applying the master theorem',sheet:R`4T(n/2)+n:\ n^{\log_24}=n^2\gg n\Rightarrow\Theta(n^2)`,
 q:R`\(T(n)=4T(n/2)+n\) solves to:`,
 o:[R`\(\Theta(n^2)\)`,R`\(\Theta(n\log n)\)`,R`\(\Theta(n)\)`,R`\(\Theta(n^2\log n)\)`],a:0,
 why:R`\(n^{\log_24}=n^2\) outgrows \(f(n)=n\), so the leaves dominate. With \(f(n)=n^2\) it would be \(\Theta(n^2\log n)\).`},
{id:'recn',t:'cx',u:'recur',lv:1,k:'mcq',name:'Subtract-one recurrences',sheet:R`T(n)=T(n-1)+n\Rightarrow\Theta(n^2);\ \ T(n)=T(n-1)+1\Rightarrow\Theta(n)`,
 q:R`\(T(n)=T(n-1)+n\) with \(T(1)=1\) solves to:`,
 o:[R`\(\Theta(n^2)\)`,R`\(\Theta(n\log n)\)`,R`\(\Theta(n)\)`,R`\(\Theta(2^n)\)`],a:0,
 why:R`Unrolling gives \(n+(n-1)+\dots+1=\frac{n(n+1)}{2}\). This is quick sort's worst case and selection sort.`},
{id:'hanoi',t:'cx',u:'recur',lv:1,k:'nat',name:'Towers of Hanoi',sheet:R`T(n)=2T(n-1)+1,\ T(1)=1\Rightarrow T(n)=2^n-1`,
 q:R`Moving 6 disks in the Towers of Hanoi takes \(T(n)=2T(n-1)+1\) moves, \(T(1)=1\). How many moves for 6 disks?`,n:{v:63},
 why:R`\(T(n)=2^n-1=63\). Two recursive calls on n − 1 each make it exponential.`},
{id:'charroot',t:'cx',u:'recur',lv:3,k:'mcq',name:'Linear recurrences',sheet:R`T(n)=c_1T(n-1)+c_2T(n-2):\ \text{roots of }x^2=c_1x+c_2`,
 q:R`\(T(n)=5T(n-1)-6T(n-2)\) with \(T(0)=1,\ T(1)=2\). Then:`,
 o:[R`\(T(n)=2^n\)`,R`\(T(n)=3^n\)`,R`\(T(n)=3^n-2^n\)`,R`\(T(n)=2\cdot3^n-2^n\)`],a:0,
 why:R`\(x^2-5x+6=0\) gives roots 2 and 3, so \(T(n)=\alpha2^n+\beta3^n\). The initial values force \(\alpha=1,\ \beta=0\).`},

/* ---------- Multiple select (MSQ) ---------- */
{id:'msqstable',t:'sort',u:'elemsort',lv:2,k:'msq',name:'Stable sorts',sheet:R`\text{stable: insertion, bubble, merge;\ not: selection, quick}`,
 q:R`Which of these sorts are stable in their standard array implementations?`,
 o:[R`Insertion sort`,R`Merge sort`,R`Selection sort`,R`Bubble sort`],a:[0,1,3],
 ex:[R`It only shifts past strictly larger elements.`,R`On ties, take from the left half.`,R`A long-distance swap can jump past an equal element.`,R`It swaps only strictly out-of-order neighbours.`],
 why:R`Stability breaks when equal keys can leapfrog each other.`},
{id:'msqbest',t:'sort',u:'elemsort',lv:2,k:'msq',name:'O(n) on sorted input',sheet:R`\text{sorted input: insertion }O(n),\ \text{bubble with early exit }O(n)`,
 q:R`Which sorts run in \(O(n)\) time on an array that is already sorted?`,
 o:[R`Insertion sort`,R`Bubble sort that stops after a pass with no swaps`,R`Selection sort`,R`Merge sort`],a:[0,1],
 ex:[R`One comparison per element.`,R`The first pass makes no swaps, so it stops.`,R`It still scans for the minimum every pass: \(\Theta(n^2)\).`,R`Always \(\Theta(n\log n)\).`],
 why:R`Adaptive sorts benefit from existing order; selection and merge sort don't.`},
{id:'msqbst',t:'ds',u:'bst',lv:2,k:'msq',name:'BST facts',sheet:R`\text{inorder sorted; height}\ge\lfloor\log_2n\rfloor;\ \text{search }O(h)`,
 q:R`A BST holds n distinct keys. Which statements are true?`,
 o:[R`An inorder traversal lists the keys in increasing order`,R`Its height is at least \(\lfloor\log_2n\rfloor\)`,R`Search always takes \(O(\log n)\) time`,R`The minimum is found by following left children from the root`],a:[0,1,3],
 ex:[R`BST property.`,R`A binary tree of height h holds at most \(2^{h+1}-1\) nodes.`,R`A skewed BST has height \(n-1\).`,R`Smaller keys are always to the left.`],
 why:R`Good bounds need balance; a plain BST can degrade to a list.`},
{id:'msqtree',t:'ds',u:'tree',lv:2,k:'msq',name:'Binary tree counts',sheet:R`n\ \text{nodes}: n-1\ \text{edges};\ L\le I+1;\ L=I+1\ \text{iff full}`,
 q:R`A binary tree has n nodes, L leaves and I internal nodes. Which statements are true for every binary tree?`,
 o:[R`\(L\le I+1\)`,R`It has \(n-1\) edges`,R`Its height is at least \(\lceil\log_2(n+1)\rceil-1\)`,R`\(L=I+1\)`],a:[0,1,2],
 ex:[R`Nodes with one child make L smaller.`,R`Every node except the root has one parent edge.`,R`From the maximum node count at each height.`,R`Only when every node has 0 or 2 children.`],
 why:R`Equality \(L=I+1\) needs a full binary tree.`},
{id:'msqhash',t:'ds',u:'hash',lv:2,k:'msq',name:'Open addressing',sheet:R`\alpha\le1;\ \text{deletions need tombstones; linear probing clusters}`,
 q:R`Which statements about open-addressing hash tables are true?`,
 o:[R`The load factor can't exceed 1`,R`Deleting a key needs a "deleted" marker so later searches don't stop early`,R`Linear probing suffers from primary clustering`,R`Worst-case search time is \(O(1)\)`],a:[0,1,2],
 ex:[R`Each slot holds one key.`,R`An empty slot would end a probe sequence that should continue.`,R`Runs grow as keys join them.`,R`Many keys in one probe sequence give \(O(n)\).`],
 why:R`Constant time is the expected case, not the worst case.`},
{id:'msqtrav',t:'graph',u:['bfs','dfs'],lv:2,k:'msq',name:'BFS and DFS facts',sheet:R`\text{BFS: queue, shortest edge counts; DFS: stack; both }O(V+E)`,
 q:R`For an undirected graph stored as adjacency lists, which statements are true?`,
 o:[R`BFS from s finds the fewest-edge path from s to every reachable vertex`,R`DFS classifies every edge as a tree edge or a back edge`,R`BFS is implemented with a stack`,R`Both BFS and DFS run in \(O(V+E)\) time`],a:[0,1,3],
 ex:[R`It explores by increasing distance.`,R`Cross and forward edges don't occur in undirected DFS.`,R`BFS uses a queue; DFS uses a stack.`,R`Each vertex and edge is handled a constant number of times.`],
 why:R`Swap the queue for a stack and BFS becomes DFS.`},
{id:'msqsp',t:'graph',u:'sp',lv:2,k:'msq',name:'Shortest-path facts',sheet:R`\text{Dijkstra: }w\ge0;\ \text{Bellman–Ford: negative weights and cycles; BFS: unweighted}`,
 q:R`Which statements are true?`,
 o:[R`Dijkstra's algorithm is correct with negative edge weights if there are no negative cycles`,R`Bellman–Ford can detect a negative cycle reachable from the source`,R`BFS solves single-source shortest paths in unweighted graphs`,R`Adding the same positive constant to every edge keeps every shortest path the same`],a:[1,2],
 ex:[R`It can finalise a vertex too early; a later negative edge could have improved it.`,R`An improvement in round V signals one.`,R`Edge counts are path lengths there.`,R`Paths with more edges grow more, so the best path can change.`],
 why:R`Know which algorithm fits which weights.`},
{id:'msqmut',t:'py',u:'pybasics',lv:1,k:'msq',name:'Mutable Python types',sheet:R`\text{mutable: list, dict, set;\ immutable: int, float, str, tuple}`,
 q:R`Which of these Python types are mutable?`,
 o:[R`list`,R`tuple`,R`dict`,R`str`],a:[0,2],
 ex:[R`append, item assignment and more change it in place.`,R`Fixed once created.`,R`Keys can be added and removed.`,R`String methods return new strings.`],
 why:R`Mutable defaults and aliasing bugs only happen with mutable types.`},
{id:'msqrec',t:'cx',u:'recur',lv:2,k:'msq',name:'Recurrences solving to n log n',sheet:R`aT(n/b)+n\ \text{with}\ a=b\Rightarrow\Theta(n\log n)`,
 q:R`Which recurrences solve to \(\Theta(n\log n)\)?`,
 o:[R`\(T(n)=2T(n/2)+n\)`,R`\(T(n)=T(n-1)+n\)`,R`\(T(n)=4T(n/2)+n^2\)`,R`\(T(n)=3T(n/3)+n\)`],a:[0,3],
 ex:[R`Merge sort.`,R`\(\Theta(n^2)\).`,R`\(n^{\log_24}=n^2\) matches f, so \(\Theta(n^2\log n)\).`,R`\(n^{\log_33}=n\) matches f.`],
 why:R`In the master theorem, f(n) matching \(n^{\log_ba}\) adds a log factor.`},
{id:'msqll',t:'ds',u:'list',lv:2,k:'msq',name:'Linked list with head and tail',sheet:R`\text{head and tail pointers: head insert/delete, tail insert }O(1);\ \text{tail delete }O(n)`,
 q:R`A singly linked list keeps both head and tail pointers. Which operations are \(O(1)\)?`,
 o:[R`Insert at the tail`,R`Delete the tail node`,R`Insert at the head`,R`Delete the head node`],a:[0,2,3],
 ex:[R`Link after tail, move tail.`,R`You need the node before the tail, which takes a walk from the head.`,R`Point the new node at the old head.`,R`Move head to its next node.`],
 why:R`That is why a singly linked list with a tail pointer makes a good queue but a poor deque.`},
{id:'msqbin',t:'search',u:'binsearch',lv:1,k:'msq',name:'Binary search facts',sheet:R`\text{sorted array; }T(n)=T(n/2)+c;\ \le\lfloor\log_2n\rfloor+1\ \text{comparisons}`,
 q:R`Which statements about binary search are true?`,
 o:[R`It needs the data sorted`,R`It runs in \(O(\log n)\) on a sorted linked list`,R`Its recurrence is \(T(n)=T(n/2)+c\)`,R`It needs at most \(\lfloor\log_2n\rfloor+1\) three-way comparisons`],a:[0,2,3],
 ex:[R`Otherwise discarding half is unjustified.`,R`Reaching the middle of a list alone is \(O(n)\).`,R`One comparison, then half the problem.`,R`Each comparison halves the range.`],
 why:R`Binary search needs sorted data and random access.`},

/* ---------- Depth pass ---------- */
{id:'linwhen',t:'search',u:'linsearch',lv:1,k:'mcq',name:'When linear search is the right choice',sheet:R`\text{unsorted or tiny data, or no random access: linear search}`,
 q:R`When is linear search preferred over binary search?`,
 o:[R`When the data are unsorted and searched only once`,R`When the array is large and sorted`,R`When many searches will be run on the same sorted array`,R`Never; binary search is always faster`],a:0,
 why:R`Sorting first costs \(O(n\log n)\), more than one \(O(n)\) scan. For many searches, sort once and binary search after.`}
]);
})();
